/// <summary>
/// Class to post the shipment confirmation
/// </summary>
class METOrderShipmentConfirmation_SalesOrder extends METOrderShipmentConfirmation
{
}

Method.Source:
/// <summary>
/// Business logic to post the shipment
/// </summary>
/// <returns>Return tag</returns>
public boolean post()
{
    boolean         isPosted;
    AccountOrder    accountOrder;

    #OCCRetryCount
    try
    {
        ttsBegin;

        accountOrder = metSalesOrderShipmentLoadHeader.PostMultiDocument == NoYes::No ? AccountOrder::Account : AccountOrder::None;

        isPosted = this.postPackingslipInvoiceReport(metSalesOrderShipmentLoadHeader, accountOrder);

        ttsCommit;

        // CB626_TMSEngineSOPackingSlip Triggers for the TMS Engine processing on SO Delivery Note Posting
        // outside the ttscommit so in case of error does not rollback the packing slip posting
        METTMSEngineSalesOrderProccess  metTMSEngineSalesOrderProccess = METTMSEngineSalesOrderProccess::construct(METTMSEngineSalesOrderProcess::PackingSlip, metSalesOrderShipmentLoadHeader);
        metTMSEngineSalesOrderProccess.run();

    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }
    catch
    {
        exceptionTextFallThrough();
    }

    return isPosted;
}

/// <summary>
/// Method to post the invoice report
/// </summary>
/// <param name = "_shipmentLoadHeader">Shipment load leader</param>
/// <param name = "_accountOrder">Account order</param>
/// <returns>Boolean result</returns>
private boolean postPackingslipInvoiceReport(METSalesOrderShipmentLoadHeader    _shipmentLoadHeader, AccountOrder _accountOrder)
{
    boolean                         isPosted = false;
    JournalId                       jourId;
    SalesFormLetter                 salesFormLetter;

    salesFormLetter = this.postPackingSlip(_shipmentLoadHeader, _accountOrder);

    if (salesFormLetter.parmJournalRecord().TableId == tableNum(CustPackingSlipJour))
    {
        CustPackingSlipJour     jourTable;
        jourTable = salesFormLetter.parmJournalRecord();
        jourId  = jourTable.packingSlipId;

        if (jourTable)
        {
            if (!_shipmentLoadHeader.PostMultiDocument)
            {
                jourTable.METUpdateLoadShipmentId(_shipmentLoadHeader);
            }
            else
            {
                CustPackingSlipJour::METUpdateLoadShipmentLines(_shipmentLoadHeader);
            }

            isPosted = true;
        }
    }

    if (isPosted)
    {
        METSalesOrderShipmentLoadLines      shipmentLoadLines;

        if (_shipmentLoadHeader.PostMultiDocument)
        {
            while select shipmentLoadLines
                group by orderNum 
                    where shipmentLoadLines.ShipmentId == _shipmentLoadHeader.ShipmentId
            {
                salesFormLetter = this.postInvoice(shipmentLoadLines.OrderNum);
                isPosted = this.updateInvoiceDetails(salesFormLetter, _shipmentLoadHeader);
            }
        }
        else
        {
            salesFormLetter = this.postInvoiceForShipment(_shipmentLoadHeader.ShipmentId);
            isPosted = this.updateInvoiceDetails(salesFormLetter, _shipmentLoadHeader);
        }
    }
    else
    {
        throw Error (strFmt("@MET:PackingSlipError", _shipmentLoadHeader.ShipmentId));
    }

    return isPosted;
}

/// <summary>
/// Update the invoice details with shipment
/// </summary>
/// <param name = "_salesFormLetter">Sales form letter</param>
/// <param name = "_shipmentLoadHeader">Shipment laod header reference</param>
/// <returns>boolean value</returns>
public boolean updateInvoiceDetails(SalesFormLetter    _salesFormLetter, METSalesOrderShipmentLoadHeader   _shipmentLoadHeader)
{
    boolean     ret;

    if (_salesFormLetter.parmJournalRecord().TableId == tableNum(CustInvoiceJour))
    {
        CustInvoiceJour     jourTable;
        jourTable = _salesFormLetter.parmJournalRecord();

        if (jourTable)
        {
            if (!_shipmentLoadHeader.PostMultiDocument)
            {
                jourTable.METUpdateLoadShipmentId(_shipmentLoadHeader);
            }
            else
            {
                CustInvoiceJour::METUpdateLoadShipmentLines(_shipmentLoadHeader);
            }
            ret = true;
        }
    }
    else
    {
        throw Error(strFmt("@MET:InvoiceNotPosted", _shipmentLoadHeader.ShipmentId));
    }

    return ret;
}

/// <summary>
/// Method to post the packing slip
/// </summary>
/// <param name = "_shipmentLoadHeader">ShipmentLoad header table reference</param>
/// <param name = "_docStatus">Document status</param>
/// <param name = "_accountOrder"> Account order</param>
/// <returns>SalesFormLetter</returns>
public SalesFormLetter postPackingSlip(METSalesOrderShipmentLoadHeader    _shipmentLoadHeader, AccountOrder _accountOrder)
{
    SalesFormLetter                 salesFormLetter;

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::PackingSlip);

    salesFormLetter.chooseLinesQuery(this.calcQuery(_shipmentLoadHeader.ShipmentId));
    salesFormLetter.transDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    salesFormLetter.specQty(SalesUpdate::PickingList);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.printout(Printout::Current);
    salesFormLetter.printFormLetter(NoYes::No);
    salesFormLetter.usePrintManagement(NoYes::No);
    salesFormLetter.chooseLines(false, true);
    salesFormLetter.sumBy(_accountOrder);
    salesFormLetter.reArrangeNow(!_shipmentLoadHeader.PostMultiDocument);

    salesFormLetter.run();

    return salesFormLetter;
}

/// <summary>
/// Post the sales order invoice
/// </summary>
/// <param name = "_salesId">SalesId reference</param>
/// <returns>SalesFormLetter</returns>
public SalesFormLetter postInvoice(SalesId  _salesId)
{
    SalesFormLetter salesFormLetter;
    SalesLine       salesLine;
    CustPackingSlipJour custPackingSlipJour;
    TmpFrmVirtual   tmpFrmVirtual;
    List packingSlipList = new List(Types::Record);

    while select custPackingSlipJour where custPackingSlipJour.SalesId == _salesId
    {
        tmpFrmVirtual.TableNum = custPackingSlipJour.TableId;
        tmpFrmVirtual.RecordNo = custPackingSlipJour.RecId;
        tmpFrmVirtual.insert();
        packingSlipList.addEnd(tmpFrmVirtual);
    }

    if (packingSlipList.empty())
    {
        throw Error(strFmt("@MET:SOPackingError", _salesId));
    }

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);

    salesFormLetter.salesTable(SalesTable::find(_salesId));
    salesFormLetter.transDate(systemDateGet());
    salesFormLetter.specQty(SalesUpdate::PackingSlip);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.chooseLines(true);
    salesFormLetter.selectFromJournal(packingSlipList.pack());
    salesFormLetter.run();

    //NS - CB274
    if (SalesTable::find(_salesId).InterCompanyOrigin == InterCompanyOrigin::Derived)
    {
        METSalesOrderProcessHelper::processPostIntercompanySOFinalization(_salesId, CustInvoiceJour::findFromSalesId(_salesId).InvoiceId);
    }
    //NE - CB274

    return SalesFormLetter;
}

/// <summary>
/// Post the sales order invoice
/// </summary>
/// <param name = "_shipmentId">SalesId reference</param>
/// <returns>SalesFormLetter</returns>
public SalesFormLetter postInvoiceForShipment(MetShipmentId  _shipmentId)
{
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    SalesFormLetter salesFormLetter;
    SalesLine       salesLine;
    CustPackingSlipJour custPackingSlipJour;
    TmpFrmVirtual   tmpFrmVirtual;
    List packingSlipList = new List(Types::Record);

    while select custPackingSlipJour
        exists join shipmentLoadLines
            where custPackingSlipJour.SalesId == shipmentLoadLines.OrderNum &&
                  shipmentLoadLines.ShipmentId == _shipmentId
    {
        tmpFrmVirtual.TableNum = custPackingSlipJour.TableId;
        tmpFrmVirtual.RecordNo = custPackingSlipJour.RecId;
        tmpFrmVirtual.insert();
        packingSlipList.addEnd(tmpFrmVirtual);
    }

    if (packingSlipList.empty())
    {
        throw Error(strFmt("@MET:ShipmentNotDelivered", _shipmentId));
    }

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);

    salesFormLetter.transDate(systemDateGet());
    salesFormLetter.specQty(SalesUpdate::PackingSlip);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.chooseLines(true);
    salesFormLetter.selectFromJournal(packingSlipList.pack());
    salesFormLetter.run();

    //NS - CB274

    SalesTable  salesTable;

    while select salesTable
        where salesTable.InterCompanyOrigin == InterCompanyOrigin::Derived
            exists join shipmentLoadLines
                where shipmentLoadLines.OrderNum == salesTable.SalesId  &&
                    shipmentLoadLines.ShipmentId == _shipmentId
    {
        METSalesOrderProcessHelper::processPostIntercompanySOFinalization(salesTable.SalesId, CustInvoiceJour::findFromSalesId(salesTable.SalesId).InvoiceId);
    }
    //NE - CB274

    return SalesFormLetter;
}

/// <summary>
/// Calculate query based on shipment Id
/// </summary>
/// <param name = "_shipmentId">Shipment Id reference</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(WMSShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadLines  metLines;
    RefRecId                salesLineRecId;
    Query                   qry = new Query(QueryStr(SalesUpdate));
    QueryBuildDataSource    queryBuildDataSource = qry.dataSourceTable(tableNum(SalesLine));
    QueryBuildRange         queryBuildRange;
    SalesLine               salesLine;

    while select metLines
            where metLines.ShipmentId == _shipmentId
        join RecId from salesLine
            where salesLine.SalesId == metLines.ordernum &&
                salesLine.LineNum == metLines.lineNum
    {
        salesLineRecId = salesLine.RecId;
        queryBuildRange = queryBuildDataSource.addRange(fieldnum(SalesLine, RecId));
        queryBuildRange.value(SysQuery::value(salesLineRecId));
    }
    return new sysQueryRun(qry);
}
